def extract_keywords(query: str):
    # Simple keyword strategy – expand later
    tokens = re.findall(r"[A-Za-z_][A-Za-z0-9_]*", query)
    python_keywords = {"the", "a", "to", "in", "and", "where", "what"}

    filtered = [
        t for t in tokens 
