    ]
    return filtered[:5]


def extract_targets(query: str):
    # Detect patterns like function(), directories, or variables
    targets = {}

    # function_name()
    fn_match = re.findall(r"([A-Za-z_][A-Za-z0-9_]*)\s*\(", query)
    if fn_match:
        targets["function"] = fn_match[0]

    # directories like src/core or /models/
    dir_match = re.findall(r"([A-Za-z0-9_\-/]+/)", query)
    if dir_match:
        targets["directory"] = dir_match[0]

def parse_notebook(raw: str) -> str:
    """
    Extracts markdown + code cells from a .ipynb file.
    Converts them to readable text for LLMs.
    """

    try:
        import nbformat

        nb = nbformat.reads(raw, as_version=4)
    except Exception:
        return raw[:5000]

    out = []

    for cell in nb.cells:
        if cell.cell_type == "markdown":
            out.append("## Markdown Cell:\n" + cell.source)
        elif cell.cell_type == "code":
            out.append("## Code Cell:\n" + cell.source)
    # print(f"Checking Execution of parse_notebook tool: {out}")

    return "\n\n".join(out)[:8000]

